function maxScore(prices) {
  const totals = new Map();
  let best = 0;
  for (let i = 0; i < prices.length; i++) {
    const key = prices[i] - i;
    const total = (totals.get(key) ?? 0) + prices[i];
    totals.set(key, total);
    best = Math.max(best, total);
  }
  return best;
}

