function maxScore(prices) {
  // dp[j]: best score of a linear choice whose last day is j.
  const dp = [];
  for (let j = 0; j < prices.length; j++) {
    let before = 0;
    for (let i = 0; i < j; i++) {
      if (prices[j] - prices[i] === j - i && dp[i] > before) before = dp[i];
    }
    dp.push(before + prices[j]);
  }
  return Math.max(...dp);
}

