function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 1000000000 : 12;
  const groups = size === 'large' ? 1 + Math.floor(rand() * 40) : 1 + Math.floor(rand() * 3);
  // A few shared offsets make long linear runs; the rest of the days are random prices.
  const offsets = Array.from({ length: groups }, () => 1 + Math.floor(rand() * (top - n)));
  const linear = rand();
  const prices = Array.from({ length: n }, (_, i) => {
    if (rand() < linear) {
      const value = offsets[Math.floor(rand() * groups)] + i;
      if (value >= 1 && value <= top) return value;
    }
    return 1 + Math.floor(rand() * top);
  });
  return [prices];
}
